def validate_stp_config(config):
    if not isinstance(config, dict) or frozenset(config) != STP_CONFIG_KEYS:
        raise InvalidInput("bad config")
    bridges = config["bridges"]
    links = config["links"]
    delay = config["delay"]
    if (
        not isinstance(bridges, list)
        or not bridges
        or not all(isinstance(name, str) and name for name in bridges)
        or len(set(bridges)) != len(bridges)
    ):
        raise InvalidInput("bad bridges")
    if not _is_int(delay) or delay <= 0:
        raise InvalidInput("bad delay")
    if not isinstance(links, list):
        raise InvalidInput("links must be a list")
    bridge_set = set(bridges)
    ids = []
    endpoints = set()
    parsed = []
    for link in links:
        if not isinstance(link, dict) or frozenset(link) != STP_LINK_KEYS:
            raise InvalidInput("bad link")
        lid = link["id"]
        cost = link["cost"]
        up = link["up"]
        if not isinstance(lid, str) or not lid:
            raise InvalidInput("bad link id")
        ends = []
        for end in (link["x"], link["y"]):
            if (
                not isinstance(end, list)
                or len(end) != 2
                or not isinstance(end[0], str)
                or end[0] not in bridge_set
                or not isinstance(end[1], str)
                or not end[1]
            ):
                raise InvalidInput("bad link endpoint")
            ends.append((end[0], end[1]))
        if ends[0][0] == ends[1][0]:
            raise InvalidInput("link endpoints on the same bridge")
        if ends[0] in endpoints or ends[1] in endpoints:
            raise InvalidInput("duplicate link endpoint")
        endpoints.update(ends)
        if not _is_int(cost) or cost <= 0:
            raise InvalidInput("bad cost")
        if not isinstance(up, bool):
            raise InvalidInput("bad up")
        ids.append(lid)
        parsed.append(
            {"id": lid, "x": ends[0], "y": ends[1], "cost": cost, "up": up}
        )
    if len(set(ids)) != len(ids):
        raise InvalidInput("link ids must be distinct")
    return bridges, parsed, delay


def validate_stp_events(events, link_ids):
    if not isinstance(events, list):
        raise InvalidInput("events must be a list")
    result = []
    prev_t = None
    for event in events:
        if not isinstance(event, dict) or frozenset(event) != STP_EVENT_KEYS:
            raise InvalidInput("bad event")
        t = event["t"]
        lid = event["id"]
        up = event["up"]
        if not _is_int(t) or t < 0:
            raise InvalidInput("bad t")
        if prev_t is not None and t < prev_t:
            raise InvalidInput("t not monotonic")
        prev_t = t
        if not isinstance(lid, str) or not lid or lid not in link_ids:
            raise InvalidInput("bad event id")
        if not isinstance(up, bool):
            raise InvalidInput("bad up")
        result.append((t, lid, up))
    return result


def stp_converge(bridges, links):
    """按当前 up 状态计算各桥分量根、根路径开销与端口角色。"""
    parent = {name: name for name in bridges}

    def find(name):
        while parent[name] != name:
            parent[name] = parent[parent[name]]
            name = parent[name]
        return name

    adjacency = {name: [] for name in bridges}
    for link in links:
        if not link["up"]:
            continue
        (bx, px), (by, py) = link["x"], link["y"]
        rx, ry = find(bx), find(by)
        if rx != ry:
            parent[rx] = ry
        adjacency[bx].append((px, by, py, link["cost"]))
        adjacency[by].append((py, bx, px, link["cost"]))
    members_of = {}
    for name in bridges:
        members_of.setdefault(find(name), []).append(name)
    root_of = {}
    for members in members_of.values():
        root = min(members)
        for name in members:
            root_of[name] = root
    cost = {name: 0 if root_of[name] == name else None for name in bridges}
    heap = [(0, name) for name in bridges if root_of[name] == name]
    heapq.heapify(heap)
    while heap:
        current, name = heapq.heappop(heap)
        if current > cost[name]:
            continue
        for _, neighbor, _, link_cost in adjacency[name]:
            new_cost = current + link_cost
            if cost[neighbor] is None or new_cost < cost[neighbor]:
                cost[neighbor] = new_cost
                heapq.heappush(heap, (new_cost, neighbor))
    roles = {name: {} for name in bridges}
    for name in bridges:
        if root_of[name] == name:
            continue
        best = None
        for port, neighbor, peer_port, link_cost in adjacency[name]:
            candidate = (cost[neighbor] + link_cost, neighbor, peer_port, port)
            if best is None or candidate < best:
                best = candidate
        if best is not None:
            roles[name][best[3]] = "root"
    for link in links:
        if not link["up"]:
            continue
        (bx, px), (by, py) = link["x"], link["y"]
        vector_x = (root_of[bx], cost[bx], bx, px)
        vector_y = (root_of[by], cost[by], by, py)
        winner = (bx, px) if vector_x < vector_y else (by, py)
        roles[winner[0]][winner[1]] = "designated"
    for link in links:
        for bridge, port in (link["x"], link["y"]):
            if link["up"]:
                roles[bridge].setdefault(port, "alternate")
            else:
                roles[bridge][port] = "disabled"
    return root_of, cost, roles


def stp(bridges, links, delay, events, max_work=None):
    """STP 公共入口：精确签名不变，返回 {"results": [...]}，无 observer 形参。

    record/replay 所需的逐事件观察逻辑封装在内部 _stp_run 中。
    """
    return _stp_run(bridges, links, delay, events, max_work, observer=None)


def _stp_run(bridges, links, delay, events, max_work=None, observer=None):
    by_id = {link["id"]: link for link in links}
    B = len(bridges)
    L = len(links)

    def up_count():
        return sum(1 for link in links if link["up"])

    def work_for(up):
        return B + L + 2 * up

    # 仅当 up 链路集合改变时才真正收敛；幂等事件复用缓存结果。
    # 先以独立链路状态无副作用预演，累计工作量超限即在仿真前报错。
    # 工作量初值 B+L+2U（t=0 收敛）；每次 up 实际改变后按新 U 再加同式，
    # 幂等事件不加；等于上限合法，首次超过即抛 StpWorkLimit。
    work = 0
    up = up_count()
    work += work_for(up)  # 初始 t=0 收敛
    sim_up = {lid: link["up"] for lid, link in by_id.items()}
    for _t, lid, new_up in events:
        if sim_up[lid] != new_up:
            sim_up[lid] = new_up
            up += 1 if new_up else -1
            work += work_for(up)
    if max_work is not None and work > max_work:
        raise StpWorkLimit

    if observer is not None:  # record：逐事件记录 applied 与事件后快照
        observer["items"] = []
    previous = {}  # (bridge, port) -> 上一轮角色
    since = {}  # (bridge, port) -> 获得当前 root/designated 角色的时刻
    results = []
    cached = None  # 最近一次实际收敛的 (root_of, cost, roles)

    def snapshot(t):
        nonlocal cached
        if cached is None:
            cached = stp_converge(bridges, links)
        root_of, cost, roles = cached
        for name in bridges:
            for port, role in roles[name].items():
                key = (name, port)
                if role in STP_TIMED_ROLES:
                    if previous.get(key) != role:  # 同角色不重计时
                        since[key] = t
                else:
                    since.pop(key, None)
        previous.clear()
        for name in bridges:
            for port, role in roles[name].items():
                previous[(name, port)] = role
        entry = {"t": t, "bridges": []}
        for name in bridges:
            ports = []
            for port in sorted(roles[name]):
                role = roles[name][port]
                if role in STP_TIMED_ROLES:
                    elapsed = t - since[(name, port)]
                    if elapsed < delay:
                        state = "discarding"
                    elif elapsed < 2 * delay:
                        state = "learning"
                    else:
                        state = "forwarding"
                else:
                    state = "discarding"
                ports.append({"name": port, "role": role, "state": state})
            entry["bridges"].append(
                {
                    "name": name,
                    "root": root_of[name],
                    "cost": cost[name],
                    "ports": ports,
                }
            )
        results.append(entry)

    snapshot(0)  # 初始 t=0 快照不写入记录
    for t, lid, new_up in events:
        applied = by_id[lid]["up"] != new_up  # up 实际改变才 applied
        if applied:
            by_id[lid]["up"] = new_up
            cached = None
        snapshot(t)
        if observer is not None:
            observer["items"].append(
                {"kind": "link", "t": t, "applied": applied,
                 "output": results[-1]}
            )
    return {"results": results}


def validate_loop_detect_config(config):
    if not isinstance(config, dict) or frozenset(config) != LOOP_CONFIG_KEYS:
        raise InvalidInput("bad config")
    vlans = config["vlans"]
    if (
        not isinstance(vlans, list)
        or not vlans
        or not all(_is_int(v) and 1 <= v <= 4094 for v in vlans)
        or any(vlans[i] >= vlans[i + 1] for i in range(len(vlans) - 1))
    ):
        raise InvalidInput("bad vlans")
    # 链路项在 stp 契约上增加 vlans：CONFIG.vlans 的严格递增非空子集
    raw_links = config["links"]
    if not isinstance(raw_links, list) or any(
        not isinstance(link, dict) or frozenset(link) != LOOP_LINK_KEYS
        for link in raw_links
    ):
        raise InvalidInput("bad link")
    stp_config = {
        "bridges": config["bridges"],
        "links": [
            {
                "id": link["id"],
                "x": link["x"],
                "y": link["y"],
                "cost": link["cost"],
                "up": link["up"],
            }
            for link in raw_links
        ],
        "delay": 1,
    }
    bridges, links, _delay = validate_stp_config(stp_config)
    vlan_set = set(vlans)
    for link, raw_link in zip(links, config["links"]):
        link_vlans = raw_link["vlans"]
        if (
            not isinstance(link_vlans, list)
            or not link_vlans
            or not all(_is_int(v) and v in vlan_set for v in link_vlans)
            or any(
                link_vlans[i] >= link_vlans[i + 1]
                for i in range(len(link_vlans) - 1)
            )
        ):
            raise InvalidInput("bad link vlans")
        link["vlans"] = link_vlans
    return bridges, links, vlans


def loop_detect(links, vlans, events, max_work=None, observer=None):
    """逐 VLAN 以桥为并查集顶点做生成树扫描：连接不同分量的 up 链路
    列入 forwarding 并合并，已连通者列入 blocked。

    每个快照计 V*(L+1)；先以独立链路状态无副作用预演，累计超限即在
    仿真前报错。t=0 先输出快照，随后每个事件（含幂等事件）应用后输出。
    observer 非 None 时（record/replay）逐事件记录 applied 与事件后快照。
    """
    by_id = {link["id"]: link for link in links}
    V = len(vlans)
    L = len(links)
    # 每个快照计 V*(L+1)；快照数为 t=0 加每个事件（含幂等事件）
    work = (1 + len(events)) * V * (L + 1)
    if max_work is not None and work > max_work:
        raise LoopWorkLimit

    if observer is not None:  # record：逐事件记录 applied 与事件后快照
        observer["items"] = []
    ordered_ids = sorted(by_id, key=lambda lid: [ord(char) for char in lid])
    results = []

    def snapshot(t):
        entries = []
        for vlan in vlans:
            parent = {}
            for link in links:
                parent.setdefault(link["x"][0], link["x"][0])
                parent.setdefault(link["y"][0], link["y"][0])

            def find(name):
                while parent[name] != name:
                    parent[name] = parent[parent[name]]
                    name = parent[name]
                return name

            forwarding = []
            blocked = []
            for lid in ordered_ids:
                link = by_id[lid]
                if not link["up"] or vlan not in link["vlans"]:
                    continue
                rx, ry = find(link["x"][0]), find(link["y"][0])
                if rx != ry:
                    forwarding.append(lid)
                    parent[rx] = ry
                else:
                    blocked.append(lid)
            entries.append(
                {"vlan": vlan, "forwarding": forwarding, "blocked": blocked}
            )
        results.append({"t": t, "vlans": entries})

    snapshot(0)
    for t, lid, new_up in events:
        changed = by_id[lid]["up"] != new_up
        by_id[lid]["up"] = new_up
        snapshot(t)
        if observer is not None:
            observer["items"].append(
                {"kind": "link", "t": t, "applied": changed,
                 "output": results[-1]}
            )
    return {"results": results}


def valid_dst_mac(value):
    """目的 MAC：小写规范、非零，允许单播与组播（含广播）。"""
    if not isinstance(value, str) or MAC_RE.fullmatch(value) is None:
        return False
    return any(int(part, 16) for part in value.split(":"))


